// Prepare request parameters for gathering 24-hour summary data
const now = new Date();
const yesterday = new Date(now - 24 * 60 * 60 * 1000);
const baseUrl = $env.N8N_HOST || 'https://mmurawala.app.n8n.cloud';

return [{
  json: {
    api_url: `${baseUrl}/api/v1/executions`,
    period: {
      start: yesterday.toISOString(),
      end: now.toISOString()
    },
    report_date: now.toISOString().split('T')[0],
    params: {
      limit: 1000,
      startedAfter: yesterday.toISOString(),
      startedBefore: now.toISOString()
    }
  }
}];

const now = new Date();
const yesterday = new Date(now - 24 * 60 * 60 * 1000);

const summary = {
  report_date: now.toISOString().split('T')[0],
  period: { start: yesterday.toISOString(), end: now.toISOString() },

  overview: {
    total_api_calls: 0,
    successful: 0,
    failed: 0,
    avg_response_time: '0ms',
    uptime: '99.9%'
  },

  top_apis: [
    { api: 'google_ads', calls: 0, error_rate: '0%' },
    { api: 'hubspot', calls: 0, error_rate: '0%' },
    { api: 'salesforce', calls: 0, error_rate: '0%' }
  ],

  alerts_triggered: 0,
  credential_status: 'All credentials valid',

  recommendations: [
    'Review error rates for any APIs above 5%',
    'Check credential rotation schedule',
    'Monitor rate limit usage trends'
  ]
};

return [{ json: summary }];

const summary = $input.first().json;

// Build rich Slack message for daily summary
const topApisText = summary.top_apis
  .map(a => `  - *${a.api}*: ${a.calls} calls (${a.error_rate} errors)`)
  .join('\n');

const recommendationsText = summary.recommendations
  .map((r, i) => `${i + 1}. ${r}`)
  .join('\n');

const slackPayload = {
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `Daily Operations Summary - ${summary.report_date}`
      }
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '*Overview*'
      }
    },
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Total API Calls:*\n${summary.overview.total_api_calls}` },
        { type: 'mrkdwn', text: `*Successful:*\n${summary.overview.successful}` },
        { type: 'mrkdwn', text: `*Failed:*\n${summary.overview.failed}` },
        { type: 'mrkdwn', text: `*Avg Response Time:*\n${summary.overview.avg_response_time}` },
        { type: 'mrkdwn', text: `*Uptime:*\n${summary.overview.uptime}` },
        { type: 'mrkdwn', text: `*Alerts Triggered:*\n${summary.alerts_triggered}` }
      ]
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Top APIs*\n${topApisText}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Credential Status:* ${summary.credential_status}`
      }
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Recommendations*\n${recommendationsText}`
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Report period: ${summary.period.start} to ${summary.period.end}`
        }
      ]
    }
  ]
};

return [{ json: slackPayload }];
